ALTER TABLE public.ride_requests ADD COLUMN series_id uuid, ADD COLUMN series_index integer, ADD COLUMN series_evidence jsonb, ADD COLUMN passenger_count integer DEFAULT 1, ADD COLUMN wheelchair_positions integer DEFAULT 0;
ALTER TABLE public.trips ADD COLUMN assignment_end_time time, ADD COLUMN passenger_count integer DEFAULT 1, ADD COLUMN wheelchair_positions integer DEFAULT 0;
CREATE UNIQUE INDEX request_series_occurrence_unique ON public.ride_requests(actor_user_id,series_id,series_index) WHERE series_id IS NOT NULL;
ALTER TABLE public.ride_requests ADD CONSTRAINT request_series_pair CHECK ((series_id IS NULL AND series_index IS NULL) OR (series_id IS NOT NULL AND series_index BETWEEN 0 AND 99)), ADD CONSTRAINT request_passenger_capacity CHECK(passenger_count BETWEEN 1 AND 50 AND wheelchair_positions BETWEEN 0 AND passenger_count);
CREATE FUNCTION public.assign_trip_resources(_trip uuid,_driver uuid,_vehicle uuid,_time time,_end time DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;ws uuid;v public.vehicles;svc text;st timestamp;en timestamp;BEGIN SELECT * INTO t FROM public.trips WHERE id=_trip FOR UPDATE;IF t.id IS NULL OR t.trip_kind<>'passenger' OR t.status IN ('completed','canceled','cancelled','no_show') THEN RAISE EXCEPTION 'An active passenger trip is required';END IF;ws:=coalesce(t.contractor_assigned_workspace_id,t.network_provider_workspace_id);IF ws IS NULL THEN SELECT r.workspace_id INTO ws FROM public.ride_requests r WHERE r.id=t.ride_request_id AND r.provider_owned_operation;END IF;IF ws IS NULL AND (t.created_by=auth.uid() OR t.assigned_to=auth.uid()) THEN SELECT CASE WHEN count(*)=1 THEN min(m.workspace_id::text)::uuid END INTO ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=auth.uid() AND m.removed_at IS NULL AND w.account_type='provider' AND w.status='active';END IF;IF ws IS NULL OR NOT public.network_workspace_access(ws,true) THEN RAISE EXCEPTION 'Provider workspace trip management permission required';END IF;
PERFORM 1 FROM public.workspaces WHERE id=ws FOR UPDATE;
svc:=CASE WHEN t.transport_type='gurney' THEN 'stretcher' ELSE t.transport_type END;
IF _driver IS NOT NULL THEN PERFORM 1 FROM public.drivers WHERE id=_driver AND workspace_id=ws FOR UPDATE;IF NOT FOUND OR NOT public.business_record_access(ws,'drivers',_driver,'read') OR NOT public.provider_driver_available(_driver,ws,svc,t.pickup_date) THEN RAISE EXCEPTION 'Active eligible driver in this workspace required';END IF;END IF;
IF _vehicle IS NOT NULL THEN SELECT * INTO v FROM public.vehicles WHERE id=_vehicle AND workspace_id=ws FOR UPDATE;IF v.id IS NULL OR NOT public.business_record_access(ws,'vehicles',_vehicle,'read') OR NOT public.pass4p_service_eligible(ws,svc,_vehicle) OR v.capacity<coalesce(t.passenger_count,1) OR (svc='wheelchair' AND coalesce(v.wheelchair_capacity,0)<greatest(coalesce(t.wheelchair_positions,0),1)) THEN RAISE EXCEPTION 'Active eligible workspace vehicle with sufficient passenger and wheelchair capacity required';END IF;END IF;
IF _driver IS NOT NULL OR _vehicle IS NOT NULL THEN IF _time IS NULL THEN RAISE EXCEPTION 'Review the schedule start time';END IF;st:=t.pickup_date+_time;en:=CASE WHEN _end IS NOT NULL THEN t.pickup_date+_end WHEN t.estimated_duration_seconds>0 THEN st+make_interval(secs=>t.estimated_duration_seconds) WHEN t.round_trip AND t.return_pickup_time IS NOT NULL THEN coalesce(t.return_date,t.pickup_date)+t.return_pickup_time ELSE NULL END;IF en IS NULL OR en<=st THEN RAISE EXCEPTION 'Provide a reviewed end time to check scheduling conflicts';END IF;IF EXISTS(SELECT 1 FROM public.trips x WHERE x.id<>t.id AND x.status NOT IN ('completed','canceled','cancelled','no_show') AND ((_driver IS NOT NULL AND x.driver_id=_driver) OR (_vehicle IS NOT NULL AND x.vehicle_id=_vehicle)) AND (x.pickup_date+coalesce(x.scheduled_start_time,x.pickup_time))<en AND coalesce(CASE WHEN x.assignment_end_time IS NOT NULL THEN x.pickup_date+x.assignment_end_time END,CASE WHEN x.estimated_duration_seconds>0 THEN x.pickup_date+coalesce(x.scheduled_start_time,x.pickup_time)+make_interval(secs=>x.estimated_duration_seconds) END,CASE WHEN x.round_trip THEN coalesce(x.return_date,x.pickup_date)+x.return_pickup_time END,(x.pickup_date+1)::timestamp)>st) THEN RAISE EXCEPTION 'Driver or vehicle time conflict; the previous assignment is unchanged';END IF;END IF;
UPDATE public.trips SET driver_id=_driver,vehicle_id=_vehicle,scheduled_start_time=_time,assignment_end_time=_end WHERE id=t.id;
INSERT INTO public.trip_dispatch_events(trip_id,event_type,vendor,payload) VALUES(t.id,'resources_assigned','mfn',jsonb_build_object('actor_id',auth.uid(),'workspace_id',ws,'before_driver',t.driver_id,'before_vehicle',t.vehicle_id,'driver_id',_driver,'vehicle_id',_vehicle,'start',_time,'end',_end));END $$;
REVOKE ALL ON FUNCTION public.assign_trip_resources(uuid,uuid,uuid,time,time) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.assign_trip_resources(uuid,uuid,uuid,time,time) TO authenticated;
CREATE OR REPLACE FUNCTION public.network_assign_driver_slot(_trip uuid,_driver uuid,_time time) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;BEGIN SELECT * INTO t FROM public.trips WHERE id=_trip FOR UPDATE;PERFORM public.assign_trip_resources(_trip,_driver,t.vehicle_id,_time,t.assignment_end_time);END $$;
CREATE FUNCTION public.owned_trip_capacity_snapshot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT r.passenger_count,r.wheelchair_positions INTO NEW.passenger_count,NEW.wheelchair_positions FROM public.ride_requests r WHERE r.id=NEW.ride_request_id;NEW.passenger_count:=coalesce(NEW.passenger_count,1);NEW.wheelchair_positions:=coalesce(NEW.wheelchair_positions,CASE WHEN NEW.transport_type='wheelchair' THEN 1 ELSE 0 END);RETURN NEW;END $$;
CREATE TRIGGER owned_trip_capacity_snapshot BEFORE INSERT ON public.trips FOR EACH ROW EXECUTE FUNCTION public.owned_trip_capacity_snapshot();
COMMENT ON COLUMN public.ride_requests.series_evidence IS 'Bounded occurrence review evidence; each request has its own immutable MFN identity. No whole-series automatic edits.';